{"code": "import os
import re

base_path = '/home/zhouhuijuan1987/wiki/youtube-video-research-wiki'

def get_title_from_file(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception:
        return os.path.basename(filepath).replace('.md', '')
    # Extract title from frontmatter
    if content.startswith('---'):
        parts = content.split('---', 2)
        if len(parts) >= 3:
            fm = parts[1]
            for line in fm.split('\n'):
                if line.strip().startswith('title:'):
                    return line.split(':', 1)[1].strip()
    # Fallback to filename
    return os.path.basename(filepath).replace('.md', '')

# Files we created
new_files = [
    'wiki/sources/S6XCelOhZ6w-hermes-agent-notebooklm-knowledge-base.md',
    'wiki/entities/notebooklm.md',
    'wiki/concepts/知识库.md',
    'wiki/concepts/多模态输出.md',
    'wiki/concepts/自动化.md',
]

sources = []
entities = []
concepts = []

for f in new_files:
    full_path = os.path.join(base_path, f)
    title = get_title_from_file(full_path)
    if f.startswith('wiki/sources/'):
        sources.append(title)
    elif f.startswith('wiki/entities/'):
        entities.append(title)
    elif f.startswith('wiki/concepts/'):
        concepts.append(title)

print("Sources:", sources)
print("Entities:", entities)
print("Concepts:", concepts)

# Format for Telegram message
source_list = '、'.join(sources) if sources else '无'
entity_list = '、'.join(entities[:5]) if entities else '无'  # limit to 5
concept_list = '、'.join(concepts[:5]) if concepts else '无'  # limit to 5

message = f'''[YOUTUBE-WIKI-RUN]
run_id=gh-25590625044-1
新增 source: {len(sources)}个 - {source_list}
新增 entity: {len(entities)}个 - {entity_list}
新增 concept: {len(concepts)}个 - {concept_list}
commit: 3997d27
log: logs/webhook-runs/gh-25590625044-1.md'''

print("\nTelegram message:")
print(message)"}
